function d_uq_montecarlo(P,R){var n=P.n||2000,sum=0,sum2=0;for(var i=0;i<n;i++){var u1=Math.max(1e-9,R()),u2=R();var z=Math.sqrt(-2*Math.log(u1))*Math.cos(2*Math.PI*u2);var x=(P.mean||10)+(P.std||1.5)*z;var y=(P.a||2)*x+(P.b||3);sum+=y;sum2+=y*y;}var m=sum/n,v=sum2/n-m*m;return{samples:n,mean:+m.toFixed(4),std:+Math.sqrt(Math.max(0,v)).toFixed(4),p95:+((P.a||2)*((P.mean||10)+1.645*(P.std||1.5))+(P.b||3)).toFixed(4)};}

